const WB_LANG_KEY = 'wb-lang';
function wbCurrentLang(){
  try {
    const q = new URLSearchParams(location.search).get('lang');
    if(q === 'zh-TW' || q === 'zh-CN') return q;
    return localStorage.getItem(WB_LANG_KEY) || 'zh-CN';
  } catch(e) { return 'zh-CN'; }
}
function wbToggleLanguage(){
  const next = wbCurrentLang() === 'zh-CN' ? 'zh-TW' : 'zh-CN';
  try { localStorage.setItem(WB_LANG_KEY, next); } catch(e){}
  try {
    const url = new URL(location.href);
    url.searchParams.set('lang', next);
    location.href = url.toString();
  } catch(e) { location.reload(); }
}
const WB_I18N_TERMS = Object.keys(I18N_S2T).sort((a,b) => b.length - a.length);
let wbI18nApplying = false;
function wbTranslateText(value){
  let out = String(value || '');
  for(const term of WB_I18N_TERMS){
    if(out.indexOf(term) !== -1) out = out.split(term).join(I18N_S2T[term]);
  }
  return out;
}
function wbTranslatable(node){
  const el = node && node.nodeType === 1 ? node : (node && node.parentElement);
  if(!el) return true;
  const tag = (el.tagName || '').toLowerCase();
  return tag !== 'script' && tag !== 'style' && tag !== 'template' && tag !== 'noscript';
}
function wbTranslateElement(el){
  if(!el || !wbTranslatable(el)) return;
  if(el.nodeType === 3){
    const n = wbTranslateText(el.nodeValue);
    if(n !== el.nodeValue) el.nodeValue = n;
    return;
  }
  if(el.nodeType !== 1) return;
  for(const attr of ['title','placeholder','aria-label']){
    const v = el.getAttribute(attr);
    if(v){ const n = wbTranslateText(v); if(n !== v) el.setAttribute(attr, n); }
  }
  for(const child of Array.from(el.childNodes)) wbTranslateElement(child);
}
function wbApplyLanguage(){
  const lang = wbCurrentLang();
  document.documentElement.lang = lang === 'zh-TW' ? 'zh-Hant-TW' : 'zh-CN';
  const btn = document.getElementById('langToggleBtn');
  if(btn){
    btn.textContent = lang === 'zh-TW' ? '繁' : '简';
    btn.title = lang === 'zh-TW' ? '当前繁體（台灣），点击切换简体' : '当前简体，点击切换繁體（台灣）';
  }
  if(lang !== 'zh-TW') return;
  if(wbI18nApplying) return;
  wbI18nApplying = true;
  try { wbTranslateElement(document.body); } finally { wbI18nApplying = false; }
}
const wbI18nObserver = typeof MutationObserver !== 'undefined' ? new MutationObserver(mutations => {
  if(wbI18nApplying || wbCurrentLang() !== 'zh-TW') return;
  wbI18nApplying = true;
  try {
    for(const m of mutations){
      if(m.type === 'childList'){
        m.addedNodes.forEach(n => wbTranslateElement(n));
      } else if(m.type === 'characterData'){
        if(wbTranslatable(m.target)){
          const n = wbTranslateText(m.target.nodeValue);
          if(n !== m.target.nodeValue) m.target.nodeValue = n;
        }
      } else if(m.type === 'attributes' && m.attributeName){
        const v = m.target.getAttribute(m.attributeName);
        if(v){ const n = wbTranslateText(v); if(n !== v) m.target.setAttribute(m.attributeName, n); }
      }
    }
  } finally { wbI18nApplying = false; }
}) : null;
wbApplyLanguage();
if(wbI18nObserver) wbI18nObserver.observe(document.body, {childList:true, subtree:true, characterData:true, attributes:true, attributeFilter:['title','placeholder','aria-label']});

function openLogin(){
  const m = document.getElementById("loginModal");
  if(m) m.classList.add("show");
}

function closeLogin(){
  const m = document.getElementById("loginModal");
  if(m) m.classList.remove("show");
  if(loginTimer){ clearInterval(loginTimer); loginTimer = null; }
  if(loginState){ postJSON("/accounts/login/cancel", {state: loginState}).catch(()=>{}); loginState = null; }
}

function openLoginModal(){
  openLogin();
  const isCn = (window.VIEW_REALM === "cn");
  const rCn = document.getElementById("radioCn");
  const rIntl = document.getElementById("radioIntl");
  if(rCn) rCn.checked = isCn;
  if(rIntl) rIntl.checked = !isCn;
  triggerLoginForSelectedRealm();
}

function switchLoginRealm(realm){
  triggerLoginForSelectedRealm();
}

function restartLogin(){
  triggerLoginForSelectedRealm();
}

async function triggerLoginForSelectedRealm(){
  const checkedRadio = document.querySelector('input[name="loginRealm"]:checked');
  const realm = checkedRadio ? checkedRadio.value : (window.VIEW_REALM || "intl");
  const isCn = (realm === "cn");

  if(loginTimer){ clearInterval(loginTimer); loginTimer = null; }
  if(loginState){ postJSON("/accounts/login/cancel", {state: loginState}).catch(()=>{}); loginState = null; }

  const linkBox = document.getElementById("loginLinkBox");
  const statusBox = document.getElementById("loginStatus");
  if(linkBox) linkBox.innerHTML = "";
  if(statusBox) statusBox.textContent = "";

  const s1 = document.getElementById("step1");
  const s2 = document.getElementById("step2");
  const s3 = document.getElementById("step3");
  if(s1) s1.className = "step active";
  if(s2) s2.className = "step";
  if(s3) s3.className = "step";

  const s1Text = document.getElementById("step1Text");
  if(s1Text) s1Text.textContent = isCn ? "正在向 copilot.tencent.com (国内版) 申请授权..." : "正在向 www.workbuddy.ai (国际版) 申请授权...";

  try{
    const r = await postJSON("/accounts/login/start", {platform: "CLI", realm: realm});
    loginState = r.state;
    if(s1) s1.className = "step done";
    if(s2) s2.className = "step active";
    if(linkBox) linkBox.innerHTML =
      '<a class="login-link" href="' + esc(r.authUrl) + '" target="_blank" rel="noopener">' + esc(r.authUrl) + '</a>'
      + '<div class="hint">点击上方链接在浏览器里完成登录授权。登录完成后本窗口会自动检测并完成入池。</div>';
    pollLogin();
    loginTimer = setInterval(pollLogin, 2500);
  }catch(e){
    if(statusBox) statusBox.textContent = "发起失败: " + e.message;
    if(s1) s1.className = "step";
  }
}

async function pollLogin(){
  if(!loginState) return;
  try{
    const r = await getJSON("/accounts/login/poll?state=" + encodeURIComponent(loginState));
    const s3 = document.getElementById("step3");
    const statusBox = document.getElementById("loginStatus");
    if(s3) s3.className = "step active";
    if(statusBox) statusBox.textContent = r.message || r.status;
    if(r.status === "ok"){
      if(s3) s3.className = "step done";
      if(statusBox) statusBox.textContent = "登录成功：" + (r.account && r.account.nickname) + " 已加入账号池";
      if(loginTimer){ clearInterval(loginTimer); loginTimer = null; }
      loginState = null;
      await loadAccounts();
      setTimeout(closeLogin, 1200);
    }else if(r.status === "error" || r.status === "expired" || r.status === "unknown"){
      if(loginTimer){ clearInterval(loginTimer); loginTimer = null; }
    }
  }catch(e){}
}


window.ACTIVE_GATEWAY_REALM = "intl";
window.VIEW_REALM = "intl";
window.REALM_FILTER = "all";
