async function loadSchedulerStatus(){
  try{
    const s = await getJSON("/scheduler");
    const bar = document.getElementById("schedulerBar");
    if(!bar) return;
    const dot = document.getElementById("schedDot");
    const txt = document.getElementById("schedStatusText");
    const times = document.getElementById("schedTimes");
    const details = document.getElementById("schedulerDetails");
    const btn = document.getElementById("btnToggleSched");
    const btnTrig = document.getElementById("btnTriggerSched");

    if(dot) dot.className = s.enabled ? 'dot' : 'dot off';
    const modeText = (window.VIEW_REALM === 'intl')
      ? (s.mode_intl || '账号 Token 自动保活与凭证常驻 (每日 22:00 集中巡检)')
      : (s.mode_cn || s.mode || '整点排程');
    if(txt){ txt.textContent = s.enabled ? '运行中' : '已暂停'; txt.title = modeText; }
    if(times) times.textContent = '上次: ' + (s.last_run_time || '-') + ' · 下次: ' + (s.next_run_time || '-');
    if(btn) btn.textContent = s.enabled ? '暂停调度' : '启用调度';
    if(btnTrig) btnTrig.textContent = (window.VIEW_REALM === 'intl') ? '立即保活刷新' : '立即巡检保活';
    if(details){
      const families = [
        ['签到', s.checkin_hours, s.checkin_enabled],
        ['旅行', s.travel_hours, s.travel_enabled],
        ['保活', s.keepalive_hours, s.keepalive_enabled],
        ['夜猫', s.cat_hours, s.cat_enabled],
        ['活跃', s.daily_chat_hours, s.daily_chat_enabled],
        ['成长', s.growth_hours, s.growth_enabled]
      ].filter(item => item[1] && item[1].length);
      const bits = families.map(item => item[0] + ' ' + item[1].join('/') + (item[2] === false ? '（关）' : ''));
      const balance = s.balance_refresh || {};
      bits.push('余额刷新 ' + (balance.enabled ? ('每 ' + (balance.minutes || 5) + ' 分钟') : '关闭'));
      if(s.include_disabled_in_tasks) bits.push('保号任务覆盖已禁用账号');
      const logs = (s.logs || []).slice(-3);
      details.innerHTML = '<div>' + esc(bits.join(' · ')) + '</div>' +
        (logs.length ? '<div style="margin-top:4px;max-height:52px;overflow:auto;font-family:monospace;font-size:11px">' + logs.map(line => esc(line)).join('<br>') + '</div>' : '');
      details.style.display = 'block';
    }
  }catch(e){}
}

